// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.core/** * NOUS — Confidence Thresholds (Module 6 v4 — Step 6.1). * * Defines explicit confidence tiers for vision inference results, per strategy * v2 §"Issue 1: No Confidence Thresholds or Fallback Chains" + v4 §"Issue 12: * Missing Confidence Reporting to User". * * ## Why this matters * * v1/v2/v3 said "object detection → plant (confidence 0.91)" but never defined: *  - What's the minimum confidence threshold? *  - What happens when confidence is low? *  - How does NOUS communicate uncertainty to the user? * * v4 fixes this with **explicit confidence tiers + fallback strategies + * 4-tier TTS uncertainty reporting**. * * ## Confidence Tiers * * | Tier | Range | NER Action | Detection Action | TTS Output | * |------|-------|-----------|------------------|------------| * | HIGH | ≥ 0.85 | Extract entity | Speak with confidence | "That's a [label]." | * | MEDIUM | 0.65-0.85 | Extract entity | Speak normally | "I think that's a [label]." | * | LOW | 0.35-0.65 | Fall back to RegexPostProcessor | Display but don't speak | "I'm not sure, but it looks like a [label]." | * | REJECT | < 0.35 | Skip extraction | Suppress | "I can't tell what that is. Can you take a clearer photo?" | * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Issue 1: Confidence Thresholds</a> */object ConfidenceThresholds {    /** NER extraction: extract entities with confidence ≥ 0.60. */    const val NER_EXTRACT = 0.60f    /** NER fallback: if confidence < 0.60, fall back to RegexPostProcessor. */    const val NER_FALLBACK = 0.60f    /** Object detection: display bounding boxes with confidence ≥ 0.50. */    const val DETECTION_DISPLAY = 0.50f    /** Object detection: speak the label with confidence ≥ 0.70. */    const val DETECTION_SPEAK = 0.70f    /** Image classification: assert "It's a [label]" with confidence ≥ 0.65. */    const val CLASSIFICATION_ASSERT = 0.65f    /** Image classification: hedge "I think it's a [label]" with confidence 0.35-0.65. */    const val CLASSIFICATION_HEDGE = 0.35f    /** OCR: no threshold — raw text is always returned; post-processor validates. */    const val OCR_MINIMUM = 0.0f    /** Visual question answering: assert answer with confidence ≥ 0.70. */    const val VQA_ASSERT = 0.70f    /** Visual question answering: hedge answer with confidence 0.40-0.70. */    const val VQA_HEDGE = 0.40f    /**     * Classify a confidence value into a [ConfidenceTier].     *     * Used by all vision engines to determine how to present results.     */    fun classifyConfidence(confidence: Float): ConfidenceTier {        return when {            confidence >= 0.85f -> ConfidenceTier.HIGH            confidence >= 0.65f -> ConfidenceTier.MEDIUM            confidence >= 0.35f -> ConfidenceTier.LOW            else -> ConfidenceTier.REJECT        }    }    /**     * Generate the TTS output for a label + confidence, per v4 §"Issue 12".     *     * @param label the detected label (e.g., "Snake Plant").     * @param confidence the model's confidence (0.0-1.0).     * @return the TTS-friendly string.     */    fun formatTtsOutput(label: String, confidence: Float): String {        return when (classifyConfidence(confidence)) {            ConfidenceTier.HIGH -> "That's a $label."            ConfidenceTier.MEDIUM -> "I think that's a $label."            ConfidenceTier.LOW -> "I'm not sure, but it looks like a $label."            ConfidenceTier.REJECT -> "I can't tell what that is. Can you take a clearer photo?"        }    }    /**     * Determine if an entity should be extracted (NER) based on confidence.     */    fun shouldExtractNerEntity(confidence: Float): Boolean = confidence >= NER_EXTRACT    /**     * Determine if a detected object should be displayed (bounding box on UI).     */    fun shouldDisplayDetection(confidence: Float): Boolean = confidence >= DETECTION_DISPLAY    /**     * Determine if a detected object's label should be spoken via TTS.     */    fun shouldSpeakDetection(confidence: Float): Boolean = confidence >= DETECTION_SPEAK    /**     * Determine if an image classification result should be asserted vs hedged.     */    fun shouldAssertClassification(confidence: Float): Boolean = confidence >= CLASSIFICATION_ASSERT    /**     * Determine if an image classification result should be hedged (vs rejected).     */    fun shouldHedgeClassification(confidence: Float): Boolean =        confidence >= CLASSIFICATION_HEDGE && confidence < CLASSIFICATION_ASSERT    /**     * Determine if a classification result should be rejected entirely.     */    fun shouldRejectClassification(confidence: Float): Boolean = confidence < CLASSIFICATION_HEDGE}// ──────────────────────────────────────────────────────────────────────────/** * Confidence tier (4-level) for vision results. */enum class ConfidenceTier(val displayName: String) {    /** ≥ 0.85 — assert with full confidence. */    HIGH("High Confidence"),    /** 0.65-0.85 — speak normally. */    MEDIUM("Medium Confidence"),    /** 0.35-0.65 — hedge ("I think..."). */    LOW("Low Confidence"),    /** < 0.35 — reject. */    REJECT("Rejected"),}// ──────────────────────────────────────────────────────────────────────────/** * Wraps a vision inference result with its confidence tier. * * All vision engines return [ConfidenceTieredResult] instead of raw values, * so the Brain + UI can make tier-aware decisions. */data class ConfidenceTieredResult<T>(    val value: T?,    val confidence: Float,    val tier: ConfidenceTier,    val fallbackUsed: Boolean = false,    val fallbackReason: String? = null,) {    /** True if the result has a non-null value AND is not in the REJECT tier. */    val isUsable: Boolean        get() = value != null && tier != ConfidenceTier.REJECT    /** Alias for [isUsable] — true if the result is acceptable to use. */    val isSuccess: Boolean        get() = isUsable    companion object {        /** Create a tiered result, automatically classifying the confidence. */        fun <T> from(value: T?, confidence: Float): ConfidenceTieredResult<T> {            return ConfidenceTieredResult(                value = value,                confidence = confidence,                tier = ConfidenceThresholds.classifyConfidence(confidence),            )        }        /** Create a tiered result that fell back from a primary model to a fallback. */        fun <T> fallback(value: T?, confidence: Float, reason: String): ConfidenceTieredResult<T> {            return ConfidenceTieredResult(                value = value,                confidence = confidence,                tier = ConfidenceThresholds.classifyConfidence(confidence),                fallbackUsed = true,                fallbackReason = reason,            )        }        /** Create a REJECTED result (confidence too low). */        fun <T> rejected(confidence: Float): ConfidenceTieredResult<T> {            return ConfidenceTieredResult(                value = null,                confidence = confidence,                tier = ConfidenceTier.REJECT,            )        }    }}